#!/usr/bin/env python3
"""Validate capability contracts and generate clients/providers. No dependencies."""
import argparse, json, pathlib, re, subprocess
ROOT = pathlib.Path(__file__).resolve().parents[2]
def snake(s): return re.sub(r'(?<!^)(?=[A-Z])', '_', s).lower()
def upper(s): return ''.join(x[0].upper()+x[1:] for x in s.split('_'))
def validate(s):
    assert re.fullmatch(r'[a-z][a-z0-9_.]+',s['id']), 'invalid capability id'
    assert re.fullmatch(r'\d+\.\d+\.\d+',s['version']), 'invalid version'
    assert s['permissions'] and all(v.strip() for v in s['permissions'].values()), 'missing permission descriptions'
    for p in s['permissions']: assert p.startswith(s['id']+'.'), 'permission outside namespace'
    for op in list(s['methods'].values())+list(s['topics'].values()):
        assert op.get('permissions') and set(op['permissions'])<=set(s['permissions']), 'missing/unknown permissions'
        for key in (['request','result'] if op in s['methods'].values() else ['type']):
            assert key in op, 'missing type reference'
            if key in op: assert op[key] in s['types'], 'unknown type'
    for group,members in s.get('groups',{}).items():
        assert group.startswith(s['id']+'.') and group not in s['permissions'], 'invalid group namespace'
        assert members and set(members)<=set(s['permissions']), 'invalid group'
    for t in s['types'].values():
        assert t['type']=='object' and t.get('additionalProperties') is False, 'object types must be closed'
        assert set(t.get('required',[]))==set(t['properties']), 'all fields must be required in this schema version'
        for f in t['properties'].values():
            assert f['type'] in ['string','number','integer','boolean','array'], 'unsupported field type'
            if f['type']=='array':
                assert f['items'].get('$ref') in s['types'] and f.get('maxItems',0)>0, 'invalid array item reference or bound'
                assert all(v['type']!='array' for v in s['types'][f['items']['$ref']]['properties'].values()), 'nested arrays unsupported'
def field_type(f, mapping, language):
    if f['type'] != 'array': return mapping[f['type']]
    item=f['items']['$ref']
    return {'go':'[]'+item,'python':'list['+item+']','kotlin':'List<'+item+'>','java':item+'[]','cpp':'std::vector<'+item+'>'}[language]
def emit(path,text):
    path.parent.mkdir(parents=True,exist_ok=True); path.write_text(text)
def generate(s,out):
    name=s['id'].split('.')[-1] if s['id'].startswith('core.') else s['id'].replace('.','_'); cap=s['id']; types=dict(sorted(s['types'].items(),key=lambda item: any(f['type']=='array' for f in item[1]['properties'].values()))); methods=s['methods']; topics=s['topics']
    go=['// Code generated by capabilities/tools/generate.py; DO NOT EDIT.','package '+name,'import ("context"; "encoding/json")','type Transport interface { Call(context.Context,string,string,any,any) error; Subscribe(context.Context,string,string,func(json.RawMessage)) (func(),error) }','type Client struct { Transport Transport }','func NewClient(t Transport) *Client { return &Client{t} }']
    gt={'string':'string','number':'float64','integer':'int64','boolean':'bool'}
    for t,desc in types.items(): go.append('type '+t+' struct { '+ '; '.join(upper(k)+' '+field_type(v,gt,'go')+' `json:"'+k+'"`' for k,v in desc['properties'].items())+' }')
    for t,d in types.items():
        for key,f in d['properties'].items():
            if f.get('enum'):
                enum=t+upper(key)
                go.append('type '+enum+' string; const ('+';'.join(enum+upper(v)+' '+enum+' = "'+v+'"' for v in f['enum'])+')')
                go=[line.replace(upper(key)+' string `json:',upper(key)+' '+enum+' `json:') if line.startswith('type '+t+' struct') else line for line in go]
    go.append('type Provider interface { '+'; '.join(upper(m)+'(context.Context,'+v['request']+') ('+v['result']+',error)' for m,v in methods.items())+' }')
    for m,v in methods.items():go.append(f'func (c *Client) {upper(m)}(ctx context.Context, p {v["request"]}) ({v["result"]},error) {{ var r {v["result"]}; err:=c.Transport.Call(ctx,"{cap}","{m}",p,&r); return r,err }}')
    for t,v in topics.items():go.append(f'func (c *Client) Subscribe{upper(t)}(ctx context.Context, fn func({v["type"]})) (func(),error) {{ return c.Transport.Subscribe(ctx,"{cap}","{t}",func(raw json.RawMessage) {{ var v {v["type"]}; if json.Unmarshal(raw,&v)==nil {{ fn(v) }} }}) }}')
    go.append('func Dispatch(ctx context.Context,p Provider,method string,raw json.RawMessage)(any,error){switch method{')
    for m,v in methods.items():go.append(f'case "{m}": var q {v["request"]}; if err:=json.Unmarshal(raw,&q);err!=nil{{return nil,err}};return p.{upper(m)}(ctx,q)')
    go.append('};return nil,&UnknownMethod{method}}\ntype UnknownMethod struct { Method string };func(e *UnknownMethod)Error()string{return "unknown method: "+e.Method}')
    go.append('func DispatchTyped(ctx context.Context,p Provider,method string,request any)(any,error){switch method{')
    for m,v in methods.items():go.append(f'case "{m}": q,ok:=request.({v["request"]});if !ok{{return nil,&InvalidRequest{{method}}}};return p.{upper(m)}(ctx,q)')
    go.append('};return nil,&UnknownMethod{method}}\ntype InvalidRequest struct { Method string };func(e *InvalidRequest)Error()string{return "invalid request type: "+e.Method}')
    emit(out/'go'/name/'generated.go','\n'.join(go)+'\n')
    py=['# Generated; do not edit.','from dataclasses import dataclass, asdict','from enum import Enum','from typing import Callable, Protocol, Any, Literal','class Transport(Protocol):','    def call(self, capability: str, method: str, payload: dict) -> dict: ...','    def subscribe(self, capability: str, topic: str, callback: Callable[[dict], None]) -> Callable[[], None]: ...']
    pt={'string':'str','number':'float','integer':'int','boolean':'bool'}
    for t,d in types.items():
        for k,f in d['properties'].items():
            if f.get('enum'):py+=['class '+t+upper(k)+'(str, Enum):']+['    '+v.upper()+' = '+repr(v) for v in f['enum']]
        py+=['@dataclass','class '+t+':']+(['    '+k+': '+(t+upper(k) if v.get('enum') else field_type(v,pt,'python')) for k,v in d['properties'].items()] or ['    pass'])
        enums=[(k,f) for k,f in d['properties'].items() if f.get('enum')]
        if enums:py+=['    def __post_init__(self):']+['        self.'+k+' = '+t+upper(k)+'(self.'+k+')' for k,f in enums]
        arrays=[(k,f) for k,f in d['properties'].items() if f['type']=='array']
        if arrays: py+=['    def __post_init__(self):']+['        self.'+k+' = [v if isinstance(v, '+f['items']['$ref']+') else '+f['items']['$ref']+'(**v) for v in self.'+k+']' for k,f in arrays]
    py+=['class Client:','    def __init__(self, transport: Transport): self.transport = transport']
    for m,v in methods.items():py += [f'    def {snake(m)}(self, request: {v["request"]}) -> {v["result"]}:',f'        return {v["result"]}(**self.transport.call("{cap}", "{m}", asdict(request)))']
    for t,v in topics.items():py += [f'    def subscribe_{t}(self, callback: Callable[[{v["type"]}], None]) -> Callable[[], None]:',f'        return self.transport.subscribe("{cap}", "{t}", lambda data: callback({v["type"]}(**data)))']
    py+=['class Provider(Protocol):']+[f'    def {snake(m)}(self, request: {v["request"]}) -> {v["result"]}: ...' for m,v in methods.items()]
    py+=['def dispatch(provider: Provider, method: str, payload: dict) -> dict:']
    for m,v in methods.items():py += [f'    if method == "{m}": return asdict(provider.{snake(m)}({v["request"]}(**payload)))']
    py+=['    raise ValueError("unknown capability method")']
    emit(out/'python'/'airdeck_sdk'/'core'/(name+'.py'),'\n'.join(py)+'\n')
    kt=['// Generated; do not edit.','package com.airdeck.client.core.capability.generated','import kotlinx.serialization.Serializable','import kotlinx.serialization.SerialName','import kotlinx.serialization.json.Json','import kotlinx.serialization.json.JsonElement',f'object {upper(name)} {{','interface Transport : CapabilityTransport']
    ktypes={'string':'String','number':'Double','integer':'Long','boolean':'Boolean'}
    for t,d in types.items():
        for k,f in d['properties'].items():
            if f.get('enum'):kt.append('@Serializable enum class '+t+upper(k)+' {'+','.join('@SerialName("'+v+'") '+v.upper() for v in f['enum'])+'}')
        kt.append(('@Serializable data class '+t+'('+','.join('val '+k+':'+(t+upper(k) if v.get('enum') else field_type(v,ktypes,'kotlin')) for k,v in d['properties'].items())+')') if d['properties'] else '@Serializable class '+t)
    kt+=['class Client(private val transport:CapabilityTransport) {']
    for m,v in methods.items():kt.append(f'suspend fun {m}(request:{v["request"]}):{v["result"]} = Json.decodeFromJsonElement({v["result"]}.serializer(),transport.call("{cap}","{m}",Json.encodeToJsonElement({v["request"]}.serializer(),request)))')
    for t,v in topics.items():kt.append(f'suspend fun subscribe{upper(t)}(callback:({v["type"]})->Unit):()->Unit = transport.subscribe("{cap}","{t}") {{ callback(Json.decodeFromJsonElement({v["type"]}.serializer(),it)) }}')
    kt+=['}','}'];emit(out/'kotlin'/(upper(name)+'.kt'),'\n'.join(kt)+'\n')
    jt={'string':'String','number':'double','integer':'long','boolean':'boolean'}
    java=['// Generated; Gson supplies JSON encoding.','package com.airdeck.capabilities;','import com.google.gson.*;','import java.util.function.Consumer;',f'public final class {upper(name)} {{','public interface Transport extends CapabilityTransport {}','private static final Gson JSON = new Gson();']
    for t,d in types.items():
        for k,f in d['properties'].items():
            if f.get('enum'):java.append('public enum '+t+upper(k)+' {'+','.join('@com.google.gson.annotations.SerializedName("'+v+'") '+v.upper() for v in f['enum'])+'}')
        java.append('public static final class '+t+' { '+' '.join('public '+(t+upper(k) if v.get('enum') else field_type(v,jt,'java'))+' '+k+';' for k,v in d['properties'].items())+' }')
    java+=['public interface Provider {']+[v['result']+' '+m+'('+v['request']+' request);' for m,v in methods.items()]+['}','public static JsonObject dispatch(Provider p,String method,JsonObject payload){switch(method){']
    for m,v in methods.items():java.append(f'case "{m}": return JSON.toJsonTree(p.{m}(JSON.fromJson(payload,{v["request"]}.class))).getAsJsonObject();')
    java+=['default: throw new IllegalArgumentException("unknown method");}}','public static final class Client { private final CapabilityTransport t; public Client(CapabilityTransport t){this.t=t;}']
    for m,v in methods.items():java.append(f'public {v["result"]} {m}({v["request"]} p){{return JSON.fromJson(t.call("{cap}","{m}",JSON.toJsonTree(p).getAsJsonObject()),{v["result"]}.class);}}')
    for topic,v in topics.items():java.append(f'public Runnable subscribe{upper(topic)}(Consumer<{v["type"]}> fn){{return t.subscribe("{cap}","{topic}",raw->fn.accept(JSON.fromJson(raw,{v["type"]}.class)));}}')
    java+=['}','}'];emit(out/'java'/'com'/'airdeck'/'capabilities'/(upper(name)+'.java'),'\n'.join(java)+'\n')
    cpp=['// Generated; requires nlohmann/json.hpp.','#pragma once','#include <nlohmann/json.hpp>','#include "capability_transport.hpp"','#include <functional>','#include <string>','#include <vector>',f'namespace airdeck::{name} {{','using json=nlohmann::json;','using Transport=airdeck::Transport;']
    ct={'string':'std::string','number':'double','integer':'int64_t','boolean':'bool'}
    for t,d in types.items():
        for k,f in d['properties'].items():
            if f.get('enum'):
                enum=t+upper(k);cpp.append('enum class '+enum+' {'+','.join(f['enum'])+'};')
                cpp.append('NLOHMANN_JSON_SERIALIZE_ENUM('+enum+', {'+','.join('{'+enum+'::'+v+',"'+v+'"}' for v in f['enum'])+'})')
        cpp.append('struct '+t+' {'+' '.join((t+upper(k) if v.get('enum') else field_type(v,ct,'cpp'))+' '+k+'{};' for k,v in d['properties'].items())+'};')
        if d['properties']:cpp.append('NLOHMANN_DEFINE_TYPE_NON_INTRUSIVE('+t+','+','.join(d['properties'])+')')
        else:cpp.append(f'inline void to_json(json& j,const {t}&){{j=json::object();}} inline void from_json(const json&,{t}&){{}}')
    cpp+=['struct Provider { virtual ~Provider()=default;']+[f'virtual {v["result"]} {m}({v["request"]})=0;' for m,v in methods.items()]+['};','inline json dispatch(Provider& p,const std::string& method,const json& q){']
    for m,v in methods.items():cpp.append(f'if(method=="{m}") return p.{m}(q.get<{v["request"]}>());')
    cpp+=['throw std::runtime_error("unknown method");}','struct Client { Transport& t;']
    for m,v in methods.items():cpp.append(f'{v["result"]} {m}({v["request"]} q){{return t.call("{cap}","{m}",q).get<{v["result"]}>();}}')
    for t,v in topics.items():cpp.append(f'std::function<void()> subscribe{upper(t)}(std::function<void({v["type"]})> fn){{return this->t.subscribe("{cap}","{t}",[fn](json j){{fn(j.get<{v["type"]}>());}});}}')
    cpp+=['};','}'];emit(out/'cpp'/(name+'.hpp'),'\n'.join(cpp)+'\n')
def check_compatibility(current, baseline):
    assert current['id']==baseline['id'], 'capability identity changed'
    if current['version'].split('.')[0]!=baseline['version'].split('.')[0]: return
    for section in ['types','methods','topics']:
        for name,definition in baseline[section].items():
            assert current[section].get(name)==definition, 'breaking '+section+' change requires a major version: '+name
    for permission in baseline['permissions']:
        assert permission in current['permissions'], 'removed permission requires a major version'
def main():
    ap=argparse.ArgumentParser();ap.add_argument('--schemas',type=pathlib.Path,default=ROOT/'capabilities/schemas');ap.add_argument('--out',type=pathlib.Path,default=ROOT/'capabilities/generated');ap.add_argument('--baseline',type=pathlib.Path);ap.add_argument('--host-root',type=pathlib.Path,help='Also generate private app integration assets under this checkout');a=ap.parse_args()
    schemas=[json.loads(p.read_text()) for p in sorted(a.schemas.glob('*.json'))]
    assert len({s['id'] for s in schemas})==len(schemas),'duplicate capability'
    for s in schemas:
        validate(s)
        if a.baseline:
            old=a.baseline/(s['id']+'.json')
            if old.exists():check_compatibility(s,json.loads(old.read_text()))
        generate(s,a.out)
    emit(a.out/'java/com/airdeck/capabilities/CapabilityTransport.java','package com.airdeck.capabilities;\nimport com.google.gson.JsonObject;\nimport java.util.function.Consumer;\npublic interface CapabilityTransport {JsonObject call(String capability,String method,JsonObject payload);Runnable subscribe(String capability,String topic,Consumer<JsonObject> callback); }\n')
    emit(a.out/'cpp/capability_transport.hpp','#ifndef AIRDECK_CAPABILITY_TRANSPORT_HPP\n#define AIRDECK_CAPABILITY_TRANSPORT_HPP\n#include <nlohmann/json.hpp>\n#include <functional>\n#include <string>\nnamespace airdeck { struct Transport {virtual nlohmann::json call(std::string,std::string,nlohmann::json)=0;virtual std::function<void()> subscribe(std::string,std::string,std::function<void(nlohmann::json)>)=0;virtual ~Transport()=default;};}\n#endif\n')
    emit(a.out/'kotlin/CapabilityTransport.kt','package com.airdeck.client.core.capability.generated\nimport kotlinx.serialization.json.JsonElement\ninterface CapabilityTransport {suspend fun call(capability:String,method:String,payload:JsonElement):JsonElement;suspend fun subscribe(capability:String,topic:String,callback:(JsonElement)->Unit):()->Unit}\n')
    if a.schemas.resolve()==(ROOT/'capabilities/schemas').resolve():
        if a.host_root:
            host=a.host_root.resolve()
            emit(host/'pc_app/assets/capabilities.json',json.dumps(schemas,indent=2)+'\n')
            raw=json.dumps(schemas,separators=(',',':'))
            emit(host/'firmware/internal/capability/contracts_generated.go','// Code generated; DO NOT EDIT.\npackage capability\nconst CoreContractsJSON = `'+raw+'`\n')
        for p in (a.out/'python/airdeck_sdk/core').glob('*.py'):emit(ROOT/'deck-plugins/sdk/python/airdeck_sdk/core'/p.name,p.read_text())
    subprocess.run(['gofmt','-w',str(a.out/'go')],check=True)
if __name__=='__main__':main()
